/**
 * BlockEditor
 *
 * Full create/edit form for one event block. Keeps a deep-cloned working copy in
 * memory; scalar fields are synced from the DOM before every structural action
 * (add/remove selector or tier), so nothing is lost across re-renders. Saving
 * validates the block before persisting. The test tool resolves a fictional total
 * against the working copy and never creates a ChatMessage.
 */

import { MODULE_ID, ROLL_TYPES, SCHEMA_VERSION } from "../constants.js";
import { getKeyLabel, listRollKeys } from "../adapters/dnd5e-roll-adapter.js";
import { activate } from "../controllers/activation-controller.js";
import { upsertBlock } from "../services/block-repository.js";
import { resolveResponse } from "../services/response-resolver.js";
import { validateBlock } from "../services/validation-service.js";
import type {
  DuplicatePolicy,
  EventBlock,
  ParticipantMode,
  ResolutionMode,
  ResponseBranch,
  ResponseTier,
  RollType
} from "../types.js";
import { refreshBlockLibrary } from "./block-library.js";

const { ApplicationV2, HandlebarsApplicationMixin } = foundry.applications.api;

const PARTICIPANT_MODES: ParticipantMode[] = [
  "all_players",
  "selected_tokens",
  "selected_actors",
  "selected_users"
];
const DUPLICATE_POLICIES: DuplicatePolicy[] = [
  "accept_all",
  "first_per_actor",
  "replace_previous",
  "ask_gm"
];
const AUTO_CLOSE_MODES = ["manual", "after_roll_count", "after_each_participant"] as const;
const NATURAL_OPTIONS = ["any", "natural_1", "natural_20"] as const;

/** Build a fresh, valid-shaped empty block for the "create" flow. */
export function newBlockTemplate(): EventBlock {
  const now = new Date().toISOString();
  return {
    id: foundry.utils.randomID(),
    name: "",
    folder: "",
    description: "",
    enabled: true,
    mode: "exclusive_range",
    selectors: [],
    branches: [],
    options: {
      include_gm_in_whisper: true,
      show_total_to_gm: true,
      show_result_to_player: true,
      color_by_tier: true,
      dice_so_nice_mode: "disabled",
      duplicate_policy: "first_per_actor",
      participant_mode: "all_players",
      participant_ids: [],
      auto_close_mode: "manual",
      auto_close_roll_count: null,
      send_fallback_response: true,
      fallback_response: "",
      randomize_equal_tier_responses: true
    },
    metadata: {
      created_at: now,
      updated_at: now,
      created_by: game.user?.id ?? "",
      schema_version: SCHEMA_VERSION
    }
  };
}

/** The block editor window. */
export class BlockEditor extends HandlebarsApplicationMixin(ApplicationV2) {
  static DEFAULT_OPTIONS = {
    id: "veiled-rolls-block-editor",
    classes: ["veiled-rolls", "veiled-rolls-editor"],
    tag: "form",
    window: {
      title: "VEILED_ROLLS.Editor.Title",
      icon: "fa-solid fa-pen-to-square",
      resizable: true
    },
    position: { width: 640, height: 640 as const },
    actions: {
      addSelector: BlockEditor.onAddSelector,
      removeSelector: BlockEditor.onRemoveSelector,
      addBranch: BlockEditor.onAddBranch,
      removeBranch: BlockEditor.onRemoveBranch,
      addTier: BlockEditor.onAddTier,
      removeTier: BlockEditor.onRemoveTier,
      test: BlockEditor.onTest,
      save: BlockEditor.onSave,
      saveActivate: BlockEditor.onSaveActivate,
      cancel: BlockEditor.onCancel
    }
  };

  static PARTS = {
    body: { template: `modules/${MODULE_ID}/templates/block-editor.hbs` }
  };

  /** In-memory working copy; never a live repository reference. */
  private working: EventBlock;
  /** Currently selected tab id. */
  private activeTab = "general";
  /** Last test-tool result (paragraphs) shown in the UI. */
  private testResult: string[] | null = null;
  /** Test-tool inputs, kept across re-renders so repeated testing is quick. */
  private testSelector = "";
  private testTotal = 15;
  /** Validation errors (localized) from the last save attempt. */
  private errors: string[] = [];

  constructor(block: EventBlock, options: AnyObject = {}) {
    super(options);
    this.working = structuredClone(block);
  }

  async _prepareContext(): Promise<AnyObject> {
    const w = this.working;

    // Branch choices shown wherever a selector must point at a branch. The raw
    // id is unreadable, so the label is used as soon as the GM provides one.
    const branchChoices = w.branches.map((b) => ({
      id: b.id,
      label: b.label?.trim() || b.id
    }));

    return {
      tab: this.activeTab,
      tabs: [
        { id: "general", label: "VEILED_ROLLS.Editor.TabGeneral" },
        { id: "rolls", label: "VEILED_ROLLS.Editor.TabRolls" },
        { id: "responses", label: "VEILED_ROLLS.Editor.TabResponses" },
        { id: "participants", label: "VEILED_ROLLS.Editor.TabParticipants" },
        { id: "options", label: "VEILED_ROLLS.Editor.TabOptions" }
      ],
      block: w,
      isExclusive: w.mode === "exclusive_range",
      modes: this.modeOptions(w.mode),
      naturalOptions: [...NATURAL_OPTIONS],
      participantModes: PARTICIPANT_MODES,
      duplicatePolicies: DUPLICATE_POLICIES,
      autoCloseModes: [...AUTO_CLOSE_MODES],
      diceModes: [
        { value: "disabled", label: "VEILED_ROLLS.Dice.disabled", selected: w.options.dice_so_nice_mode === "disabled" },
        { value: "private", label: "VEILED_ROLLS.Dice.private", selected: w.options.dice_so_nice_mode === "private" }
      ],
      participantIds: w.options.participant_ids.join("\n"),
      branchChoices,
      // Each row carries its own key list, matching that row's roll type.
      selectors: w.selectors.map((s) => ({
        ...s,
        rollTypes: this.rollTypeOptions(s.roll_type),
        keyChoices: this.keyOptions(s.roll_type, s.key),
        branches: branchChoices.map((b) => ({ ...b, selected: b.id === s.branch_id }))
      })),
      branches: w.branches.map((b) => ({
        ...b,
        displayName: b.label?.trim() || b.id,
        rollTypes: this.rollTypeOptions(b.roll_type),
        keyChoices: this.keyOptions(b.roll_type, b.key),
        tiers: b.tiers.map((t) => ({ ...t, responsesText: t.responses.join("\n") }))
      })),
      // Selectors offered to the test tool, labelled readably.
      testChoices: w.selectors.map((s) => ({
        value: `${s.roll_type}|${s.key}`,
        label: s.label?.trim() || getKeyLabel(s.roll_type, s.key) || s.key,
        selected: `${s.roll_type}|${s.key}` === this.testSelector
      })),
      testTotal: this.testTotal,
      testResult: this.testResult,
      errors: this.errors
    };
  }

  /** Roll-type options with the current one flagged. */
  private rollTypeOptions(current: RollType): Array<AnyObject> {
    return ROLL_TYPES.map((value) => ({
      value,
      label: `VEILED_ROLLS.RollType.${value}`,
      selected: value === current
    }));
  }

  /**
   * Key options for a roll type. Free text was error-prone: D&D5e expects short
   * ids (`acr`, `dex`), and a skill name is invalid for an ability check.
   */
  private keyOptions(rollType: RollType, current: string): Array<AnyObject> {
    return listRollKeys(rollType).map((choice) => ({
      ...choice,
      selected: choice.value === current
    }));
  }

  /** Options for the resolution-mode select with the current one flagged. */
  private modeOptions(current: ResolutionMode): Array<AnyObject> {
    return [
      { value: "exclusive_range", label: "VEILED_ROLLS.Editor.ModeExclusive", selected: current === "exclusive_range" },
      { value: "cumulative_threshold", label: "VEILED_ROLLS.Editor.ModeCumulative", selected: current === "cumulative_threshold" }
    ];
  }

  /** The root form element of this application. */
  private get form(): HTMLFormElement | null {
    return this.element instanceof HTMLFormElement ? this.element : this.element?.querySelector?.("form") ?? null;
  }

  /** Read a scalar string value by input name from the form. */
  private field(name: string): string {
    const el = this.form?.elements.namedItem(name) as HTMLInputElement | null;
    return el?.value ?? "";
  }

  /** Read a checkbox value by input name. */
  private checked(name: string): boolean {
    const el = this.form?.elements.namedItem(name) as HTMLInputElement | null;
    return Boolean(el?.checked);
  }

  /**
   * Sync the DOM fields of the *currently rendered* tab into the working copy.
   *
   * Only the active tab exists in the DOM, so each group is guarded: reading a
   * field belonging to a hidden tab would return an empty string and silently
   * erase the user's data (and turn every option checkbox off).
   */
  private sync(): void {
    const w = this.working;

    // The test tool sits outside the tab body, so it is always present.
    const selector = this.field("test_selector");
    if (selector) this.testSelector = selector;
    const rawTotal = this.field("test_total");
    if (rawTotal !== "") {
      const parsed = Number(rawTotal);
      if (Number.isFinite(parsed)) this.testTotal = parsed;
    }

    if (this.activeTab === "general") {
      w.name = this.field("name").trim();
      w.folder = this.field("folder").trim();
      w.description = this.field("description");
      w.mode = (this.field("mode") as ResolutionMode) || w.mode;
    }

    if (this.activeTab === "rolls") {
      w.selectors = w.selectors.map((_, i) => {
        const rollType = (this.field(`sel-${i}-roll_type`) as RollType) || "skill";
        const key = this.field(`sel-${i}-key`).trim().toLowerCase();
        // An empty label is filled from the system's own wording for that key.
        const label = this.field(`sel-${i}-label`).trim() || getKeyLabel(rollType, key);
        return {
          roll_type: rollType,
          key,
          label,
          branch_id: this.field(`sel-${i}-branch_id`).trim()
        };
      });
    }

    if (this.activeTab === "responses") {
      w.branches = w.branches.map((b, bi) => ({
        id: b.id,
        label: this.field(`br-${bi}-label`).trim() || b.id,
        roll_type: (this.field(`br-${bi}-roll_type`) as RollType) || b.roll_type,
        key: this.field(`br-${bi}-key`).trim().toLowerCase() || b.key,
        tiers: b.tiers.map((t, ti) => this.readTier(bi, ti, t))
      }));
    }

    const opts = w.options;

    if (this.activeTab === "participants") {
      opts.participant_mode = (this.field("participant_mode") as ParticipantMode) || opts.participant_mode;
      opts.duplicate_policy = (this.field("duplicate_policy") as DuplicatePolicy) || opts.duplicate_policy;
      opts.participant_ids = this.field("participant_ids")
        .split(/[\n,]/)
        .map((s) => s.trim())
        .filter((s) => s.length > 0);
    }

    if (this.activeTab === "options") {
      opts.include_gm_in_whisper = this.checked("include_gm_in_whisper");
      opts.show_total_to_gm = this.checked("show_total_to_gm");
      opts.show_result_to_player = this.checked("show_result_to_player");
      opts.color_by_tier = this.checked("color_by_tier");
      opts.dice_so_nice_mode = (this.field("dice_so_nice_mode") as EventBlock["options"]["dice_so_nice_mode"]) || "disabled";
      opts.randomize_equal_tier_responses = this.checked("randomize_equal_tier_responses");
      opts.send_fallback_response = this.checked("send_fallback_response");
      opts.fallback_response = this.field("fallback_response");
      opts.auto_close_mode = (this.field("auto_close_mode") as EventBlock["options"]["auto_close_mode"]) || "manual";
      const count = Number(this.field("auto_close_roll_count"));
      opts.auto_close_roll_count = Number.isFinite(count) && count > 0 ? count : null;
    }
  }

  /** Parse one tier's fields from the DOM. */
  private readTier(bi: number, ti: number, current: ResponseTier): ResponseTier {
    const minRaw = this.field(`tier-${bi}-${ti}-min`).trim();
    const maxRaw = this.field(`tier-${bi}-${ti}-max`).trim();
    const responses = this.field(`tier-${bi}-${ti}-responses`)
      .split("\n")
      .map((s) => s.trim())
      .filter((s) => s.length > 0);
    return {
      id: current.id,
      minimum: minRaw === "" ? null : Number(minRaw),
      maximum: maxRaw === "" ? null : Number(maxRaw),
      responses,
      gm_note: this.field(`tier-${bi}-${ti}-gm_note`),
      natural_roll: (this.field(`tier-${bi}-${ti}-natural`) as ResponseTier["natural_roll"]) || "any",
      weighting: "equal"
    };
  }

  /**
   * Wire tab switching with a direct click listener rather than the framework's
   * `data-action` dispatch.
   *
   * ApplicationV2 reserves the `tab` action for its own tab-group handling, and
   * the exact convention varies between versions; binding the listener here makes
   * tab navigation independent of that mechanism. Listeners are re-attached on
   * every render because the elements are recreated each time.
   */
  _onRender(_context: AnyObject, _options: AnyObject): void {
    const root = this.element;
    if (!root?.querySelectorAll) return;
    for (const el of root.querySelectorAll("[data-tab-id]")) {
      el.addEventListener("click", (event: Event) => {
        event.preventDefault();
        const id = (event.currentTarget as HTMLElement)?.dataset?.tabId;
        if (!id) return;
        this.sync();
        this.activeTab = id;
        void this.render();
      });
    }

    // Changing a row's roll type must rebuild that row's key list, because
    // skills and abilities do not share the same set of valid keys.
    for (const el of root.querySelectorAll("[data-vr-refresh]")) {
      el.addEventListener("change", () => {
        this.sync();
        void this.render();
      });
    }
  }

  static onAddSelector(this: BlockEditor): void {
    this.sync();
    this.working.selectors.push({ roll_type: "skill", key: "", label: "", branch_id: "" });
    void this.render();
  }

  static onRemoveSelector(this: BlockEditor, _event: Event, target: HTMLElement): void {
    this.sync();
    const i = Number(target?.dataset?.index);
    if (Number.isInteger(i)) this.working.selectors.splice(i, 1);
    void this.render();
  }

  static onAddBranch(this: BlockEditor): void {
    this.sync();
    const branch: ResponseBranch = {
      id: foundry.utils.randomID(),
      label: "",
      roll_type: "skill",
      key: "",
      tiers: []
    };
    this.working.branches.push(branch);
    void this.render();
  }

  static onRemoveBranch(this: BlockEditor, _event: Event, target: HTMLElement): void {
    this.sync();
    const i = Number(target?.dataset?.index);
    if (Number.isInteger(i)) this.working.branches.splice(i, 1);
    void this.render();
  }

  static onAddTier(this: BlockEditor, _event: Event, target: HTMLElement): void {
    this.sync();
    const bi = Number(target?.dataset?.index);
    const branch = this.working.branches[bi];
    if (!branch) return;
    branch.tiers.push({
      id: foundry.utils.randomID(),
      minimum: null,
      maximum: null,
      responses: [],
      gm_note: "",
      natural_roll: "any",
      weighting: "equal"
    });
    void this.render();
  }

  static onRemoveTier(this: BlockEditor, _event: Event, target: HTMLElement): void {
    this.sync();
    const bi = Number(target?.dataset?.branch);
    const ti = Number(target?.dataset?.tier);
    const branch = this.working.branches[bi];
    if (branch && Number.isInteger(ti)) branch.tiers.splice(ti, 1);
    void this.render();
  }

  static onTest(this: BlockEditor): void {
    this.sync();
    const [roll_type, key] = this.testSelector.split("|");
    if (!Number.isFinite(this.testTotal) || !key) {
      this.testResult = [game.i18n.localize("VEILED_ROLLS.Editor.TestInvalid")];
      void this.render();
      return;
    }
    const resolved = resolveResponse(this.working, {
      roll_type: roll_type as RollType,
      key,
      total: this.testTotal,
      natural_result: null
    });
    this.testResult = resolved
      ? resolved.paragraphs
      : [game.i18n.localize("VEILED_ROLLS.Editor.TestNoMatch")];
    void this.render();
  }

  /** Persist the working copy; returns the saved block or null on failure. */
  private async persist(): Promise<EventBlock | null> {
    this.sync();
    this.working.metadata.updated_at = new Date().toISOString();
    const validation = validateBlock(this.working);
    if (!validation.valid) {
      this.errors = validation.errors.map((e) =>
        game.i18n.format(e.messageKey, e.data ?? {})
      );
      void this.render();
      return null;
    }
    this.errors = [];
    const result = await upsertBlock(this.working);
    if (!result.valid) {
      this.errors = result.errors.map((e) => game.i18n.format(e.messageKey, e.data ?? {}));
      void this.render();
      return null;
    }
    refreshBlockLibrary();
    return this.working;
  }

  static async onSave(this: BlockEditor): Promise<void> {
    const saved = await this.persist();
    if (saved) {
      ui.notifications?.info(game.i18n.localize("VEILED_ROLLS.Notify.Saved"));
      await this.close();
    }
  }

  static async onSaveActivate(this: BlockEditor): Promise<void> {
    const saved = await this.persist();
    if (!saved) return;
    await activate(saved);
    ui.notifications?.info(game.i18n.localize("VEILED_ROLLS.Notify.Activated"));
    await this.close();
  }

  static async onCancel(this: BlockEditor): Promise<void> {
    await this.close();
  }
}

/** Open the editor for a given block (existing or new template). */
export function openBlockEditor(block: EventBlock): void {
  void new BlockEditor(block).render({ force: true });
}
