/**
 * ControlPanel
 *
 * The GM's main window: shows the active-filter state, participants and recent
 * history, and offers activate/disable/reset actions. It is a singleton and
 * re-renders whenever the active-filter setting or history changes.
 */

import { MODULE_ID } from "../constants.js";
import { activate, disable, getState, resetParticipants } from "../controllers/activation-controller.js";
import { getBlock, getBlocks } from "../services/block-repository.js";
import { validateBlock } from "../services/validation-service.js";
import { clearHistory, getHistory, getRecentHistory } from "../services/history-service.js";
import { resendHistory } from "../services/whisper-service.js";
import {
  connectedPlayers,
  outstandingSelectorIds,
  requestRoll,
  resetRequests
} from "../services/roll-request-service.js";
import { getKeyLabel } from "../adapters/dnd5e-roll-adapter.js";
import type { HistoryEntry, RollType } from "../types.js";
import { openBlockLibrary } from "./block-library.js";
import { openBlockEditor } from "./block-editor.js";

const { ApplicationV2, HandlebarsApplicationMixin } = foundry.applications.api;

/** Format an ISO/epoch timestamp as a short local time string. */
function shortTime(value: number | string | null): string {
  if (value === null) return "—";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "—" : date.toLocaleTimeString();
}

/** The GM control panel window. */
export class ControlPanel extends HandlebarsApplicationMixin(ApplicationV2) {
  static instance: ControlPanel | null = null;

  static DEFAULT_OPTIONS = {
    id: "veiled-rolls-control-panel",
    classes: ["veiled-rolls", "veiled-rolls-panel"],
    tag: "section",
    window: {
      title: "VEILED_ROLLS.Panel.Title",
      icon: "fa-solid fa-mask",
      resizable: true
    },
    position: { width: 520, height: "auto" as const },
    actions: {
      openLibrary: ControlPanel.onOpenLibrary,
      openActive: ControlPanel.onOpenActive,
      disableFilter: ControlPanel.onDisable,
      resetParticipants: ControlPanel.onReset,
      newSession: ControlPanel.onNewSession,
      resend: ControlPanel.onResend,
      copyResponse: ControlPanel.onCopy,
      clearHistory: ControlPanel.onClearHistory
    }
  };

  static PARTS = {
    body: { template: `modules/${MODULE_ID}/templates/control-panel.hbs` }
  };

  /** Cache of the recent history for action handlers to read by id. */
  private recent: HistoryEntry[] = [];
  /** Folder names the GM has collapsed, to keep a long list readable. */
  private collapsedFolders = new Set<string>();

  /** Open (or bring to front) the singleton panel. */
  static open(): void {
    ControlPanel.instance ??= new ControlPanel();
    void ControlPanel.instance.render({ force: true });
  }

  /** Re-render the panel if it is currently open. */
  static refresh(): void {
    if (ControlPanel.instance?.rendered) void ControlPanel.instance.render();
  }

  async _prepareContext(): Promise<AnyObject> {
    const state = getState();
    const activeBlock = state.blockId ? await getBlock(state.blockId) : undefined;
    this.recent = await getRecentHistory(20);

    // "Done" persists across sessions: a roll counts as done if the kept history
    // (stored in the GM journal) holds an entry for that block + selector. It is
    // reset by starting a new session (which clears the history).
    const history = await getHistory();
    const doneSet = new Set(history.map((h) => `${h.blockId}|${h.rollType}|${h.key}`));
    const pendingKeys = outstandingSelectorIds();
    const noFolder = game.i18n.localize("VEILED_ROLLS.Panel.NoFolder");

    // Every prepared roll across every block, grouped by folder (the field the
    // GM uses as a session/chapter) so the list stays organized as it grows.
    const all = await getBlocks();
    const groups = new Map<string, AnyObject[]>();
    let remaining = 0;
    for (const block of all) {
      const valid = validateBlock(block).valid;
      const folder = block.folder?.trim() || noFolder;
      const isActiveBlock = state.active && state.blockId === block.id;
      for (const s of block.selectors) {
        const done = doneSet.has(`${block.id}|${s.roll_type}|${s.key}`);
        const requested = isActiveBlock && pendingKeys.has(`${s.roll_type}|${s.key}`);
        const status = requested ? "requested" : done ? "done" : "todo";
        if (status !== "done") remaining += 1;
        const rolls = groups.get(folder) ?? [];
        rolls.push({
          blockId: block.id,
          blockName: block.name || game.i18n.localize("VEILED_ROLLS.Library.Unnamed"),
          rollType: s.roll_type,
          key: s.key,
          label: s.label?.trim() || getKeyLabel(s.roll_type, s.key),
          valid,
          status,
          statusLabel: game.i18n.localize(`VEILED_ROLLS.RollStatus.${status}`),
          isDone: status === "done",
          isRequested: status === "requested",
          isLoaded: isActiveBlock
        });
        groups.set(folder, rolls);
      }
    }

    const folders = [...groups.entries()]
      .sort((a, b) => a[0].localeCompare(b[0]))
      .map(([name, rolls]) => ({
        name,
        collapsed: this.collapsedFolders.has(name),
        doneCount: rolls.filter((r) => r.isDone).length,
        total: rolls.length,
        rolls
      }));

    const players = connectedPlayers();

    return {
      active: state.active,
      folders,
      hasFolders: folders.length > 0,
      remaining,
      players,
      hasPlayers: players.length > 0,
      blockName: state.descriptor?.blockName ?? activeBlock?.name ?? "—",
      processedCount: state.processedCount,
      hasActiveBlock: Boolean(activeBlock),
      participants: state.participants.map((p) => ({
        actorName: p.actorName,
        status: p.status,
        statusLabel: game.i18n.localize(`VEILED_ROLLS.Status.${p.status}`),
        total: typeof p.lastTotal === "number" ? p.lastTotal : "—",
        lastRollAt: shortTime(p.lastRollAt)
      })),
      history: this.recent.map((h) => ({
        id: h.id,
        userName: h.userName,
        actorName: h.actorName,
        keyLabel: h.keyLabel,
        total: h.total,
        response: h.responseParagraphs.join(" "),
        time: shortTime(h.timestamp)
      }))
    };
  }

  /**
   * Bind the block-row controls with direct listeners rather than the framework's
   * `data-action` dispatch, which proved unreliable for these buttons. Listeners
   * are re-attached on every render because the rows are rebuilt each time.
   */
  _onRender(_context: AnyObject, _options: AnyObject): void {
    const root = this.element;
    if (!root?.querySelectorAll) return;

    // Collapse/expand a folder group to keep a long list readable.
    for (const el of root.querySelectorAll("[data-vr-folder]")) {
      el.addEventListener("click", (event: Event) => {
        event.preventDefault();
        const name = (event.currentTarget as HTMLElement)?.dataset?.vrFolder;
        if (!name) return;
        if (this.collapsedFolders.has(name)) this.collapsedFolders.delete(name);
        else this.collapsedFolders.add(name);
        void this.render();
      });
    }

    // Request a roll. "group" targets every player; "select" opens a picker to
    // choose one or more players. The button carries its block id, so a block
    // that isn't active is loaded first and the request always yields a veiled
    // roll without a separate activation step.
    for (const el of root.querySelectorAll("[data-vr-request]")) {
      el.addEventListener("click", (event: Event) => {
        event.preventDefault();
        const node = event.currentTarget as HTMLElement;
        const blockId = node?.dataset?.block;
        const rollType = node?.dataset?.vrRequest as RollType | undefined;
        const key = node?.dataset?.key;
        const target = node?.dataset?.target;
        if (!blockId || !rollType || !key || !target) return;
        void this.dispatchRequest(blockId, rollType, key, target);
      });
    }
  }

  /** Resolve the target scope (group or a player selection) and send it. */
  private async dispatchRequest(
    blockId: string,
    rollType: RollType,
    key: string,
    target: string
  ): Promise<void> {
    let targets: string[] | null;
    if (target === "group") {
      targets = null;
    } else {
      const picked = await ControlPanel.pickPlayers();
      if (!picked || picked.length === 0) return;
      targets = picked;
    }
    await this.request(blockId, rollType, key, targets);
  }

  /**
   * Prompt the GM to pick one or more connected players. Returns the chosen user
   * ids, or null if cancelled or no players are connected.
   */
  static async pickPlayers(): Promise<string[] | null> {
    const players = connectedPlayers();
    if (players.length === 0) {
      ui.notifications?.warn(game.i18n.localize("VEILED_ROLLS.Panel.RequestNoPlayers"));
      return null;
    }
    const rows = players
      .map(
        (p) =>
          `<label class="veiled-rolls-pick"><input type="checkbox" name="vr-player" value="${p.id}" checked /> ${p.name}</label>`
      )
      .join("");
    const chosen = await foundry.applications.api.DialogV2.wait({
      window: { title: game.i18n.localize("VEILED_ROLLS.Panel.PickPlayers") },
      content: `<div class="veiled-rolls-pick-list">${rows}</div>`,
      buttons: [
        {
          action: "ok",
          label: game.i18n.localize("VEILED_ROLLS.Panel.PickConfirm"),
          default: true,
          callback: (_event: Event, button: AnyObject, dialog: AnyObject) => {
            const host = dialog?.element ?? button?.form;
            const boxes = host?.querySelectorAll?.('input[name="vr-player"]:checked') ?? [];
            return Array.from(boxes).map((b) => (b as HTMLInputElement).value);
          }
        },
        { action: "cancel", label: game.i18n.localize("VEILED_ROLLS.Editor.Cancel") }
      ]
    }).catch(() => null);
    return Array.isArray(chosen) ? (chosen as string[]) : null;
  }

  /** Ensure the roll's block is active, then send the request. */
  private async request(
    blockId: string,
    rollType: RollType,
    key: string,
    targets: string[] | null
  ): Promise<void> {
    const state = getState();
    if (!state.active || state.blockId !== blockId) {
      const block = await getBlock(blockId);
      if (!block) return;
      if (!validateBlock(block).valid) {
        ui.notifications?.warn(game.i18n.localize("VEILED_ROLLS.Notify.BlockInvalid"));
        return;
      }
      resetRequests();
      await activate(block);
    }
    requestRoll(rollType, key, targets);
  }

  /**
   * Start a new session: disable the filter, reset participants and clear the
   * history. Clearing history is what resets every roll's "done" colour, giving
   * a clean slate to replay prepared blocks in the next session.
   */
  static async onNewSession(this: ControlPanel): Promise<void> {
    const ok = await foundry.applications.api.DialogV2.confirm({
      window: { title: game.i18n.localize("VEILED_ROLLS.Panel.NewSession") },
      content: `<p>${game.i18n.localize("VEILED_ROLLS.Panel.NewSessionConfirm")}</p>`
    });
    if (!ok) return;
    resetRequests();
    await disable();
    await resetParticipants();
    await clearHistory();
    ControlPanel.refresh();
  }

  /** Find a cached history entry by id. */
  private entry(id: string): HistoryEntry | undefined {
    return this.recent.find((h) => h.id === id);
  }

  static onOpenLibrary(this: ControlPanel): void {
    openBlockLibrary();
  }

  static async onOpenActive(this: ControlPanel): Promise<void> {
    const state = getState();
    if (!state.blockId) return;
    const block = await getBlock(state.blockId);
    if (block) openBlockEditor(block);
  }

  static async onDisable(this: ControlPanel): Promise<void> {
    resetRequests();
    await disable();
    ControlPanel.refresh();
  }

  static async onReset(this: ControlPanel): Promise<void> {
    await resetParticipants();
    ControlPanel.refresh();
  }

  static async onResend(this: ControlPanel, _event: Event, target: HTMLElement): Promise<void> {
    const id = target?.dataset?.id;
    const entry = id ? this.entry(id) : undefined;
    if (!entry) return;
    await resendHistory(entry);
    ui.notifications?.info(game.i18n.localize("VEILED_ROLLS.Notify.Resent"));
  }

  static async onCopy(this: ControlPanel, _event: Event, target: HTMLElement): Promise<void> {
    const id = target?.dataset?.id;
    const entry = id ? this.entry(id) : undefined;
    if (!entry) return;
    try {
      await navigator.clipboard.writeText(entry.responseParagraphs.join("\n\n"));
      ui.notifications?.info(game.i18n.localize("VEILED_ROLLS.Notify.Copied"));
    } catch {
      ui.notifications?.warn(game.i18n.localize("VEILED_ROLLS.Notify.CopyFailed"));
    }
  }

  static async onClearHistory(this: ControlPanel): Promise<void> {
    const ok = await foundry.applications.api.DialogV2.confirm({
      window: { title: game.i18n.localize("VEILED_ROLLS.Panel.ClearHistory") },
      content: `<p>${game.i18n.localize("VEILED_ROLLS.Panel.ClearHistoryConfirm")}</p>`
    });
    if (!ok) return;
    await clearHistory();
    ControlPanel.refresh();
  }
}

/** Convenience opener used by the API and scene control. */
export function openControlPanel(): void {
  ControlPanel.open();
}
